"""Contract data (docs/art/castle-kit.md "Exterior"): the grounds generated by
tools/blender/terrain_layout.py are up to date and keep their promises, and
data/world/exterior.json (the far silhouette's massing) is complete and
stands clear of every playable space. Pure Python."""

import json
import math
import os
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
sys.dont_write_bytecode = True
sys.path[:0] = [os.path.dirname(HERE), os.path.join(os.path.dirname(HERE), "world")]

import layout_lib as L  # noqa: E402
import terrain_layout as T  # noqa: E402
from castle_kit import grid as G  # noqa: E402

ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
LAYOUT = os.path.join(ROOT, "data", "world", "layout.json")
EXTERIOR = os.path.join(ROOT, "data", "world", "exterior.json")
GROUNDS = os.path.join(ROOT, "data", "world", "terrain", "grounds.json")


def load(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


class GroundsDataTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.layout = L.load_layout(LAYOUT)
        cls.grounds = load(GROUNDS)
        cls.grid = T.lattice()

    def test_generated_data_is_up_to_date(self):
        for path, body in T.outputs().items():
            with open(path, encoding="utf-8") as f:
                self.assertEqual(f.read(), body, f"{os.path.relpath(path, ROOT)}: run tools/blender/terrain_layout.py")

    def test_box_cells_and_water(self):
        g = self.grounds
        self.assertEqual((g["box"]["min"], g["box"]["max"]), ([-112.0, 92.0], [128.0, 292.0]))
        self.assertEqual(len(g["cells"]), 30)
        self.assertEqual((g["water_y"], g["wade"], g["step"]), (-15.0, 0.3, 2.0))
        self.assertEqual(g["cells"], G.P3A_GROUNDS_CELLS)
        # The pitch's stands are flat decks of the `pitch` cell.
        cells = {s.cell for s in self.layout.surfaces if s.kind == "grounds"} - {G.P3B_PITCH_CELL}
        self.assertLessEqual(cells, set(g["cells"]))
        for s in self.layout.surfaces:
            if s.kind != "grounds" or s.cell == G.P3B_PITCH_CELL:
                continue
            self.assertIsNotNone(s.heights, s.id)
            self.assertIsNone(s.ceiling, s.id)
            self.assertGreaterEqual(s.floor_min, g["water_y"] - g["wade"] - 1e-6, s.id)
            self.assertLessEqual(s.heights.max_slope(), L.MAX_GROUND_SLOPE + 1e-6, s.id)

    def test_layout_heights_are_the_lattice(self):
        for s in self.layout.surfaces:
            if s.heights is None:
                continue
            hf = s.heights
            for j in range(hf.rows):
                for i in range(hf.cols):
                    x, z = hf.origin[0] + hf.step * i, hf.origin[1] + hf.step * j
                    gi, gj = round((x - T.X0) / T.STEP), round((z - T.Z0) / T.STEP)
                    self.assertEqual(hf.h[j * hf.cols + i], self.grid[gj][gi], f"{s.id} [{x}, {z}]")

    def test_layout_is_valid_and_connected(self):
        rep = L.validate(self.layout)
        self.assertEqual(rep.errors, [])

    def test_buildings_are_holes_and_reserved_sites_walkable(self):
        def walkable(x, z):
            return any(s.contains(x, z, eps=-1e-3) for s in self.layout.surfaces if s.kind == "grounds")

        for b in self.grounds["buildings"]:
            (x0, z0), (x1, z1) = b["min"], b["max"]
            self.assertFalse(walkable((x0 + x1) / 2, (z0 + z1) / 2), b["id"])
        for r in self.grounds["reserved"]:
            c = r.get("centre") or [(r["min"][0] + r["max"][0]) / 2, (r["min"][1] + r["max"][1]) / 2]
            self.assertTrue(walkable(*c), r["id"])
        sites = self.grounds["sites"]
        self.assertEqual(sites["pitch"]["y"], -9.5)
        self.assertEqual(sites["gate_apron"]["y"], 0.0)

    def test_grounds_landmarks_stand_on_the_ground(self):
        marks = {m["id"]: m["pos"] for m in self.layout.landmarks}
        for lid in ("groundskeepers_cottage", "lake_shore", "boathouse", "stone_circle", "owl_loft_knoll", "greenhouses", "paddock"):
            x, y, z = marks[lid]
            s = L.spawn_surface(self.layout, (x, y, z))
            self.assertIsNotNone(s, lid)
            self.assertEqual(s.kind, "grounds", lid)
            self.assertAlmostEqual(s.height(x, z), y, delta=0.01, msg=lid)

    def test_place_names_match_where_you_stand(self):
        # Review fix: the top bar shows the surface's name, so the hut and the paddock gate,
        # 40 m and more from the water, are not the "Lake Shore".
        marks = {m["id"]: m["pos"] for m in self.layout.landmarks}
        want = {"lake_shore": "Lake Shore", "boathouse": "Lake Shore", "groundskeepers_cottage": "Castle Grounds",
                "paddock": "Castle Grounds", "greenhouses": "Castle Grounds", "owl_loft_knoll": "Castle Grounds"}
        for lid, name in want.items():
            x, y, z = marks[lid]
            self.assertEqual(L.spawn_surface(self.layout, (x, y, z)).name, name, lid)


class ExteriorDataTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.ext = load(EXTERIOR)
        cls.layout = L.load_layout(LAYOUT)
        cls.grounds = load(GROUNDS)

    def castle_cells(self):
        # The pitch (its stands' steps are stairs) stands on the grounds.
        # N8's and the Owl Loft's cells join their chunks when kitted.
        # So do the passages beside outer walls.
        return ({s.cell for s in self.layout.surfaces if s.kind != "grounds"} - {G.P3B_PITCH_CELL}
                - set(G.P3C_HLOD_PENDING) - set(G.P3D_HLOD_PENDING))

    def test_every_castle_cell_has_one_chunk(self):
        chunks = self.ext["chunks"]
        ids = [c["id"] for c in chunks]
        self.assertEqual(len(ids), len(set(ids)))
        self.assertTrue(G.P3A_HLOD_CHUNKS[0] <= len(chunks) <= G.P3A_HLOD_CHUNKS[1], len(chunks))
        seen = [cell for c in chunks for cell in c["cells"]] + self.ext["no_outside"]
        self.assertEqual(len(seen), len(set(seen)), "a cell in two chunks")
        self.assertEqual(set(seen), self.castle_cells())
        for cell in self.ext["no_outside"]:
            top = max(s.struct_top() for s in self.layout.surfaces if s.cell == cell)
            outdoor = [s for s in self.layout.surfaces if s.cell == cell and not s.roofed]
            self.assertEqual(outdoor, [], cell)
            self.assertLess(min(s.floor_min for s in self.layout.surfaces if s.cell == cell), 0.0, cell)
            self.assertLess(top, 30.0, cell)

    def test_masses_are_well_formed(self):
        chunks = {c["id"]: c for c in self.ext["chunks"]}
        self.assertEqual(self.ext["stone"], "castle_wall_c")  # the one outside stone: the west range's
        self.assertEqual(self.ext["roof"], "castle_roof")
        ids = set()
        for m in self.ext["masses"]:
            mid = m["id"]
            self.assertNotIn(mid, ids)
            ids.add(mid)
            self.assertIn(m["chunk"], chunks, mid)
            self.assertEqual(chunks[m["chunk"]]["cells"], [], f"{mid}: masses go in exterior-only chunks")
            self.assertIn(m["shape"], ("box", "round"), mid)
            self.assertIn(m["roof"], ("cone", "pyramid", "pitched", "flat", "none"), mid)  # none: a flat top
            if m["roof"] == "pitched":
                self.assertIn(m["ridge"], ("x", "z"), mid)
            if m["roof"] not in ("flat", "none"):
                self.assertGreater(m["roof_height"], 0, mid)
            if "over" in m:
                self.assertIn(m["over"], self.castle_cells(), mid)
                self.assertNotIn("base", m, mid)
            else:
                self.assertLess(m["base"], m["top"], mid)
        tallest = max((m for m in self.ext["masses"] if "top" in m), key=lambda m: m["top"] + m.get("roof_height", 0))
        self.assertEqual(tallest["id"], "astronomy_tower")

    def _rect(self, m):
        if m["shape"] == "round":
            (cx, cz), r = m["centre"], m["radius"]
            return cx - r, cz - r, cx + r, cz + r
        return m["min"][0], m["min"][1], m["max"][0], m["max"][1]

    def test_masses_stand_clear_of_every_playable_space(self):
        """No exterior-only mass overlaps a playable surface's volume (its
        floor to its roof) or the walkable grounds; a cap stands within its
        cell's footprint, above it."""
        for m in self.ext["masses"]:
            x0, z0, x1, z1 = self._rect(m)
            if "over" in m:
                cell = [s for s in self.layout.surfaces if s.cell == m["over"]]
                self.assertGreaterEqual(x0, min(s.x0 for s in cell) - 1e-6, m["id"])
                self.assertLessEqual(x1, max(s.x1 for s in cell) + 1e-6, m["id"])
                self.assertGreaterEqual(z0, min(s.z0 for s in cell) - 1e-6, m["id"])
                self.assertLessEqual(z1, max(s.z1 for s in cell) + 1e-6, m["id"])
                continue
            for s in self.layout.surfaces:
                if min(x1, s.x1) - max(x0, s.x0) <= 1e-6 or min(z1, s.z1) - max(z0, s.z0) <= 1e-6:
                    continue
                top = m["top"] + m.get("roof_height", 0)
                below = s.struct_top() <= m["base"] + 1e-6
                # (a roofless mass may run up to just under a floor it carries.)
                above = s.floor_min - (0.0 if m["roof"] == "none" else 1.0) >= top
                self.assertTrue(below or above, f"{m['id']} overlaps {s.id}")
            self.assertLessEqual(z1, self.grounds["box"]["min"][1], f"{m['id']} stands on the grounds")


class SeamTests(unittest.TestCase):
    """greybox.py's seams for the outdoor exports (world/outdoor.py), the
    resident cells and the open-sky rooms."""

    def test_optional_modules(self):
        import outdoor

        self.assertIsNone(outdoor.optional_module("no_such_export_p3a"))
        self.assertIsNotNone(outdoor.optional_module("outdoor"))

    def test_resident_cells(self):
        self.assertEqual(len(G.P3A_RESIDENT_CELLS), 33)
        self.assertEqual(G.P3A_RESIDENT_CELLS[-3:], ("lake", "backdrop", "foliage"))
        self.assertEqual(G.hlod_node("hlod_court", "castle_roof"), "hlod.hlod_court.castle_roof")

    def test_open_sky_rooms(self):
        import re

        src = open(os.path.join(os.path.dirname(HERE), "world", "build_school.py"), encoding="utf-8").read()
        rooms = re.search(r"OPEN_SKY_ROOMS = \(([^)]*)\)", src).group(1)
        rooms = [r.strip().strip('"') for r in rooms.split(",") if r.strip()]
        self.assertEqual(rooms, ["class_astronomy", "class_paddock", "class_pitch"])  # The Flying class
        for lid in rooms:
            data = load(os.path.join(ROOT, "data", "world", "instances", f"{lid}.json"))
            self.assertTrue(all(s.get("ceiling") is None for s in data["surfaces"]), lid)


if __name__ == "__main__":
    unittest.main()
